import type { BBox, TerrainGrid } from '../core/types';
import manifest from '../../public/data/regions.json';

/** Per-scenario map data set (generated by scripts/data/build.mjs into public/data/regions.json). */
export interface RegionFiles { terrain: string; infra: string; cities: string; boundaries: string; land: string; lakes: string }
export interface Region { id: string; title: string; bbox: BBox; cellDeg: number; files: RegionFiles }

export const REGIONS: Region[] = manifest as Region[];

const near = (a: number, b: number) => Math.abs(a - b) < 1e-6;
export const sameBBox = (a: BBox, b: BBox): boolean => near(a.west, b.west) && near(a.east, b.east) && near(a.south, b.south) && near(a.north, b.north);

/**
 * Region for a terrain grid: exact bbox match, else the smallest region containing it, else the first region.
 * (Scenarios declare their region through terrainFile; the engine hands the loaded grid to the map.)
 */
export function regionForTerrain(t: Pick<TerrainGrid, 'bbox'>): Region {
  const exact = REGIONS.find((r) => sameBBox(r.bbox, t.bbox));
  if (exact) return exact;
  const b = t.bbox;
  const area = (r: Region) => (r.bbox.east - r.bbox.west) * (r.bbox.north - r.bbox.south);
  const containing = REGIONS.filter((r) => r.bbox.west <= b.west && r.bbox.east >= b.east && r.bbox.south <= b.south && r.bbox.north >= b.north).sort((x, y) => area(x) - area(y));
  return containing[0] ?? REGIONS[0];
}

/** Region by terrain file name, e.g. 'terrain_ardennes.json'. */
export const regionForFile = (file: string): Region | undefined => REGIONS.find((r) => r.files.terrain === file || r.files.infra === file);
